import {DeckStore,validateDeck,indexCards} from './deck-model.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let config,csrf;
async function api(action,data){if(!config){const r=await fetch('deck-config.json');config=await r.json();}if(!config.api)throw Error('Online-Konten werden auf blutbank.nussbaum.page eingerichtet. / Online accounts will be available on blutbank.nussbaum.page.');
 const u=new URL(config.api,location.href);if(u.origin!==location.origin)throw Error('Invalid API origin');u.searchParams.set('action',action);
 const r=await fetch(u,{method:data?'POST':'GET',credentials:'same-origin',headers:data?{'Content-Type':'application/json','X-CSRF-Token':csrf||''}:{},body:data?JSON.stringify(data):undefined});let result;try{result=await r.json()}catch{throw Error('Server nicht verfügbar / Server unavailable');}if(!r.ok)throw Error(result.error||'Server error');if(result.csrf)csrf=result.csrf;return result;
}
export async function saveOnline(deck){await api('session');const result=await api('save',{deck,revision:deck.remoteRevision??null});const store=new DeckStore(),all=store.read(),i=all.findIndex(d=>d.id===deck.id);if(i>=0){all[i].remoteRevision=result.revision;store.storage.setItem(store.key,JSON.stringify(all));}return result;}
export async function mountAccount(root,cards,lang){
 const t=(d,e)=>lang==='en'?e:d;root.innerHTML=`<h1>${t('Konto & Online-Decks','Account & online decks')}</h1><p role="status" id="account-status">${t('Verbindung wird geprüft …','Checking connection …')}</p>`;
 try{
  let session=await api('session');if(!root.querySelector('#account-status'))return;
  const params=new URLSearchParams(location.hash.split('?')[1]||'');
  if(params.has('token')){const token=params.get('token');history.replaceState(null,'',`#/${lang}/account`);session=await api('login',{token});}
  if(!session.user){root.innerHTML=`<h1>${t('Anmelden','Sign in')}</h1><p>${t('Du erhältst einen einmaligen Anmeldelink per E-Mail. Ein Passwort ist nicht nötig.','Receive a one-time sign-in link by email. No password needed.')}</p><form class="account-form"><label>E-Mail<input type="email" name="email" autocomplete="email" required maxlength="254"></label><button class="pill">${t('Anmeldelink anfordern','Send sign-in link')}</button></form><p id="account-status" role="status"></p><a href="#/${lang}/decks">${t('Ohne Anmeldung weiterbauen','Continue without signing in')}</a>`;root.querySelector('form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{await api('request-login',{email:new FormData(e.target).get('email'),lang});root.querySelector('#account-status').textContent=t('Wenn der Versand möglich ist, erhältst du einen Link. Er gilt 15 Minuten.','If delivery is available, you will receive a link valid for 15 minutes.');}catch(e){root.querySelector('#account-status').textContent=e.message}finally{button.disabled=false}};return;}
  const {decks}=await api('list');root.innerHTML=`<h1>${t('Online-Decks','Online decks')}</h1><p>${esc(session.user.email)}</p><button id="logout" class="pill">${t('Abmelden','Sign out')}</button><a class="pill" href="#/${lang}/decks">${t('Lokale Decks bearbeiten','Edit local decks')}</a><p id="account-status" role="status"></p>${decks.map(d=>`<article class="online-deck"><h3>${esc(d.deck.name)}</h3><p>${d.deck.trashed?t('Im Papierkorb','In trash'):t('Privat, sofern nicht per Link freigegeben','Private unless shared by link')}</p><button class="pill" data-load="${esc(d.deck.id)}">${t('Deck öffnen','Open deck')}</button><button class="pill" data-share="${esc(d.deck.id)}">${t('Freigabelink erstellen','Create sharing link')}</button><button class="pill" data-unshare="${esc(d.deck.id)}">${t('Freigabe beenden','Revoke sharing')}</button></article>`).join('')||`<p>${t('Noch keine Online-Decks. Im Editor „Online speichern“ wählen.','No online decks yet. Select “Save online” in the editor.')}</p>`}`;
  root.querySelector('#logout').onclick=async()=>{await api('logout',{});mountAccount(root,cards,lang);};
  const identities=await (await fetch('data/card-identities.json')).json(),index=indexCards(cards,identities);
  root.querySelectorAll('[data-load]').forEach(b=>b.onclick=()=>{try{const remote=decks.find(x=>x.deck.id===b.dataset.load),d={...structuredClone(remote.deck),remoteRevision:remote.revision},store=new DeckStore(),existing=store.read().find(x=>x.id===d.id);if(existing&&(JSON.stringify(existing.entries)!==JSON.stringify(d.entries)||existing.name!==d.name||existing.description!==d.description)){const backup={...existing,id:crypto.randomUUID(),name:(existing.name+' · '+t('Lokale Sicherung','Local backup')).slice(0,120)};delete backup.remoteRevision;store.save(backup,index);}validateDeck(d,index);store.save(d,index);location.hash=`#/${lang}/decks/${d.id}`;}catch(e){root.querySelector('#account-status').textContent=e.message;}});
  for(const kind of ['share','unshare'])root.querySelectorAll(`[data-${kind}]`).forEach(b=>b.onclick=async()=>{try{const r=await api(kind,{id:b.dataset[kind]});const out=root.querySelector('#account-status');out.textContent=kind==='share'?t('Freigabelink: ','Sharing link: '):t('Freigabe beendet.','Sharing revoked.');if(r.token){const a=document.createElement('a');a.href=`#/${lang}/shared/${r.token}`;a.textContent=new URL(a.href).href;out.append(a);}}catch(e){root.querySelector('#account-status').textContent=e.message;}});
 }catch(e){const el=root.querySelector('#account-status');if(el)el.textContent=e.message;}
}
export async function mountShared(root,cards,lang,token){const t=(d,e)=>lang==='en'?e:d;root.innerHTML=`<p id="shared-status">${t('Deck wird geladen …','Loading deck …')}</p>`;try{await api('session');const {deck}=await api('read-shared',{token});root.innerHTML=`<h1>${esc(deck.name)}</h1><p>${esc(deck.description)}</p><button class="pill" id="shared-copy">${t('Als eigenes Deck speichern','Save as own deck')}</button><ul>${deck.entries.map(e=>`<li>${e.quantity}× ${esc(cards.find(c=>c.id===e.printingId)?.name||e.cardId)}</li>`).join('')}</ul>`;root.querySelector('#shared-copy').onclick=async()=>{const idx=indexCards(cards,await (await fetch('data/card-identities.json')).json());const d={...deck,id:crypto.randomUUID(),trashed:false};delete d.remoteRevision;new DeckStore().save(d,idx);location.hash=`#/${lang}/decks/${d.id}`;};}catch(e){root.querySelector('#shared-status').textContent=e.message;}}
